package com.estoqueinteligente.supplier;
import java.net.URI;import java.util.List;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/suppliers")public class SupplierController{private final SupplierService service;public SupplierController(SupplierService service){this.service=service;}@GetMapping public List<SupplierResponse> findAll(){return service.findAll();}@GetMapping("/{id}")public SupplierResponse findById(@PathVariable Long id){return service.findById(id);}@PostMapping public ResponseEntity<SupplierResponse> create(@Valid @RequestBody SupplierRequest request){SupplierResponse created=service.create(request);return ResponseEntity.created(URI.create("/suppliers/"+created.getId())).body(created);}@PutMapping("/{id}")public SupplierResponse update(@PathVariable Long id,@Valid @RequestBody SupplierRequest request){return service.update(id,request);}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();}}
